import {scenario} from './scenarios.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const NEWS_URL='https://raw.githubusercontent.com/devrafag/civitas-world-lab/main/dist/news.json';
export function setupAnalysis({show,getSelected}){
 let profiles=null,news=null,remote=false,country='ESP',other='MAR',mode='news',trigger='diplomacy';
 const date=s=>{const d=new Date(s);return Number.isFinite(d.getTime())?d.toLocaleString('es',{dateStyle:'medium',timeStyle:'short'}):'Sin fecha'};
 function validate(s){if(!s||s.schemaVersion!==1||!Array.isArray(s.items)||!Array.isArray(s.sources))throw Error('Formato inválido');const ids=new Set(profiles.map(p=>p.id));s.items=s.items.slice(0,80).filter(n=>typeof n.title==='string'&&n.title.length<=350&&typeof n.url==='string'&&n.url.startsWith('https://')&&Array.isArray(n.countries)&&n.countries.every(c=>ids.has(c))&&Number.isFinite(Date.parse(n.publishedAt)));return s}
 async function load(){if(!profiles){const r=await fetch('./profiles.json');if(!r.ok)throw Error();profiles=(await r.json()).profiles}try{const r=await fetch(NEWS_URL,{cache:'no-store',signal:AbortSignal.timeout(6500)});if(!r.ok)throw Error();news=validate(await r.json());remote=true}catch{remote=false;const r=await fetch('./news.json');if(!r.ok)throw Error();news=validate(await r.json())}}
 function item(n){return `<article class="newsitem"><a href="${esc(n.url)}" target="_blank" rel="noopener">${esc(n.title)}</a><small>${esc(n.source)} · Publicación: ${date(n.publishedAt)}</small><p>Mención por palabras del titular. Fecha del acontecimiento sin verificar. Leer y contrastar la fuente.</p></article>`}
 const options=(id)=>profiles.map(p=>`<option value="${p.id}" ${p.id===id?'selected':''}>${esc(p.name)}</option>`).join('');
 function render(){const p=profiles.find(p=>p.id===country)||profiles[0];country=p.id;let body='';
 if(mode==='news'){const items=news.items.filter(n=>n.countries.includes(country));const age=Date.now()-Date.parse(news.lastSuccessfulFetch);body=`<p class="dossiernotice">${remote?'Última copia disponible en GitHub':'Copia incluida en esta versión; conexión a GitHub no disponible'}<br>Última recuperación correcta: ${date(news.lastSuccessfulFetch)}${!Number.isFinite(age)||age>24*3600000?'<br><b>Datos antiguos o sin recuperación confirmada.</b>':''}<br>No es un servicio de noticias en tiempo real.</p><div class="sourcehealth">${news.sources.map(s=>`<p>${esc(s.name)}: <b>${s.ok?'consulta correcta':'consulta fallida'}</b> · ${date(s.checkedAt)}</p>`).join('')}</div><button id="refreshNews">Consultar última copia</button><p class="factnote">Solo se incluyen titulares recientes que nombran países de la lista. La ausencia de titulares no significa ausencia de tensión. Una coincidencia de nombres no demuestra conflicto.</p>${items.length?items.map(item).join(''):'<p>No hay titulares asociados a este país en la copia consultada.</p>'}`}
 else{if(other===country)other=profiles.find(p=>p.id!==country).id;const b=profiles.find(p=>p.id===other),s=scenario(p,b,trigger,news.items);body=`<label for="secondCountry">Segundo país</label><select id="secondCountry">${options(other)}</select><label for="trigger">Supuesto que tú introduces</label><select id="trigger"><option value="diplomacy" ${trigger==='diplomacy'?'selected':''}>Ruptura de conversaciones</option><option value="trade" ${trigger==='trade'?'selected':''}>Interrupción comercial</option><option value="incident" ${trigger==='incident'?'selected':''}>Incidente no atribuido</option></select><p class="dossiernotice"><b>HIPÓTESIS, NO SUCESO CONFIRMADO</b><br>${esc(s.kind)} Las noticias no activan este supuesto ni cambian el simulador.</p><h3>${esc(s.title)}</h3><ul>${s.constraints.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${s.paths.map(x=>`<section class="scenario"><h3>${esc(x.name)}</h3><p><b>Condición:</b> ${esc(x.condition)}</p><p>${esc(x.outcome)}</p></section>`).join('')}<h3>Titulares que mencionan a ambos</h3><p class="factnote">Contexto por coincidencia textual, sin validación de relación causal.</p>${s.items.length?s.items.map(item).join(''):'<p>No hay coincidencias en esta copia. No se extrae ninguna conclusión de ello.</p>'}`}
 show(`<div class="eyebrow">OBSERVATORIO / FUENTES Y SUPUESTOS</div><h2>Noticias y escenarios</h2><div class="analysisnav"><button id="newsMode" aria-pressed="${mode==='news'}">Noticias</button><button id="scenarioMode" aria-pressed="${mode==='scenario'}">Escenarios</button></div><label for="analysisCountry">País observado</label><select id="analysisCountry">${options(country)}</select>${body}`);
 document.getElementById('newsMode').onclick=()=>{mode='news';render()};document.getElementById('scenarioMode').onclick=()=>{mode='scenario';render()};document.getElementById('analysisCountry').onchange=e=>{country=e.target.value;render()};if(mode==='news')document.getElementById('refreshNews').onclick=async()=>{const button=document.getElementById('refreshNews');button.disabled=true;button.textContent='Consultando…';try{await load();render()}catch{button.disabled=false;button.textContent='Consulta fallida · reintentar'}};else{document.getElementById('secondCountry').onchange=e=>{other=e.target.value;if(other===country)country=profiles.find(p=>p.id!==other).id;render()};document.getElementById('trigger').onchange=e=>{trigger=e.target.value;render()}}
 }
 document.getElementById('analysis').onclick=async()=>{show('<h2>Consultando el observatorio…</h2><p>Recuperando titulares y fichas.</p>');try{await load();country=profiles.some(p=>p.id===getSelected())?getSelected():'ESP';render()}catch{show('<h2>No se pudo abrir el observatorio</h2><p>Las fuentes no están disponibles. Cierra y vuelve a intentarlo.</p>')}};
}
